/* Inline stijlen: data-st wordt via CSSOM toegepast (zonder unsafe-inline in de CSP). Synchroon bij innerHTML. */
(function(){
  function applyST(root){
    if(!root||root.nodeType!==1)return;
    const list=root.hasAttribute('data-st')?[root]:[];
    if(root.querySelectorAll)list.push(...root.querySelectorAll('[data-st]'));
    for(const el of list){el.style.cssText=el.getAttribute('data-st');el.removeAttribute('data-st')}
  }
  const d=Object.getOwnPropertyDescriptor(Element.prototype,'innerHTML');
  Object.defineProperty(Element.prototype,'innerHTML',{configurable:true,enumerable:d.enumerable,get:d.get,set(v){d.set.call(this,v);applyST(this)}});
  const ins=Element.prototype.insertAdjacentHTML;
  Element.prototype.insertAdjacentHTML=function(p,h){ins.call(this,p,h);applyST(this.parentNode||this)};
  applyST(document.documentElement);
  new MutationObserver(ms=>{for(const m of ms)for(const n of m.addedNodes)applyST(n)}).observe(document.documentElement,{childList:true,subtree:true});
  document.addEventListener('DOMContentLoaded',()=>applyST(document.documentElement));
})();
